import {project,object} from '../document/model.js';import {putKey} from '../animation/evaluate.js';
export function demo(){const p=project();p.name='A little motion';p.background='#faf9ff';const bg=object('rectangle',{name:'Backdrop',x:100,y:105,width:1080,height:510,fill:'#efedf9',radius:24,locked:true});const circle=object('ellipse',{name:'Orbit',x:235,y:280,width:120,height:120,fill:'#f0b94a'});for(const [t,x,y,s] of [[0,235,280,1],[2,580,180,1.25],[4,895,300,.8],[6,235,280,1]]){for(const [k,v] of [['x',x],['y',y],['scaleX',s],['scaleY',s]])putKey(circle,k,t,v);}const path=object('path',{name:'Ribbon',x:480,y:305,fill:'#6760e8',closed:true,nodes:[{x:0,y:85,out:{x:100,y:-60}},{x:220,y:20,out:{x:270,y:90}},{x:220,y:120},{x:0,y:150}]});putKey(path,'fill',0,'#6760e8');putKey(path,'fill',3,'#ed8098');putKey(path,'fill',6,'#6760e8');const label=object('text',{name:'Draw it. Tween it.',x:355,y:495,text:'Draw it. Tween it.',fontSize:48,width:600,height:60,fill:'#38354e'});const tiny=object('group',{name:'Nested shapes',children:[object('rectangle',{x:0,y:0,width:38,height:38,fill:'#ae9de7',rotation:15}),object('ellipse',{x:60,y:0,width:38,height:38,fill:'#e5a6b7'})]});const group=object('group',{name:'Little constellation',x:925,y:155,anchorX:45,anchorY:30,children:[tiny,object('ellipse',{x:35,y:60,width:24,height:24,fill:'#7fb7a5'})]});putKey(group,'rotation',0,-10);putKey(group,'rotation',3,35);putKey(group,'rotation',6,-10);putKey(group,'opacity',0,.7);putKey(group,'opacity',3,1);p.layers=[bg,path,circle,group,label];return p;}
